if not mainline:
    return True
return (card.rank % 2) != (mainline[-1].rank % 2)

if not mainline:
    return True
prev = mainline[-1]
if prev.color == "red":
    # rank must increase, allowing King (13) -> Ace (1)
    return card.rank > prev.rank or (prev.rank == 13 and card.rank == 1)
else:  # prev.color == "black"
    # rank must decrease, allowing Ace (1) -> King (13)
    return card.rank < prev.rank or (prev.rank == 1 and card.rank == 13)
